    def __find_alias(self):
        """Alias substitution within the AST.

        This method replaces aliases in the document names and updates the root, level, const dictionaries accordingly. It iterates through the alias dictionary to find matches in the document names and performs substitutions.

        Parameters:
            self (Parser): The Parser instance.

        Returns:
            None

        Examples:
            >>> p = Parser()
            >>> p.alias = {'alias1': 'root', 'alias2': 'child'}
            >>> p.doc = {'root': 'document1', 'root.child': 'document2', 'other': 'document3'}
            >>> p.root = {'root': 'root', 'root.child': 'root.child'}
            >>> p.level = {'root': 0, 'root.child': 1}
            >>> p.const = {'root': 'constant1', 'root.child': 'constant2'}
            >>> p.__find_alias()
            >>> print(p.doc)  # Output: {'root': 'document1', 'root.child': 'document2', 'root.child.alias2': 'document2'}
            >>> print(p.root)  # Output: {'root': 'root', 'root.child': 'root.child', 'root.child.alias2': 'root.child'}
            >>> print(p.level)  # Output: {'root': 0, 'root.child': 1, 'root.child.alias2': 1}
            >>> print(p.const)  # Output: {'root': 'constant1', 'root.child': 'constant2', 'root.child.alias2': 'constant2'}
        """
